import{_ as e,c as p,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"坤下坤上 坤：","description":"京氏易传 - 坤下坤上 坤：","frontmatter":{"title":"坤下坤上 坤：","description":"京氏易传 - 坤下坤上 坤："},"headers":[],"relativePath":"zh/classics/jingshi/034.md","filePath":"zh/classics/jingshi/034.md"}'),i={name:"zh/classics/jingshi/034.md"};function r(n,a,c,_,o,l){return t(),p("div",null,[...a[0]||(a[0]=[s('<h1 id="坤下坤上-坤" tabindex="-1">坤下坤上 坤： <a class="header-anchor" href="#坤下坤上-坤" aria-label="Permalink to “坤下坤上 坤：”">​</a></h1><p>纯阴用事，象配地，属土。柔道光也，阴凝感，与乾相纳，臣奉君也。《易》云：“黄裳，元吉”。六二，内卦阴处中</p><p>，臣道正也。与乾为飞伏，【癸酉金，壬戌土。】宗庙居世，三公为应。未免龙战之灾，无成有终。【阴臣阳君，臣不敢为</p><p>物之始。阳唱阴和，君命臣终其事也。】初六起履霜，至于坚冰。阴虽柔顺，气亦坚刚，为无邪气也。</p><p>建始甲午至己亥，【芒种，小满。】积算起己亥至戊戌，周而复始。【纯土用事，入积算，定吉凶。】</p><p>五星从位起太阴，【太阴水星入卦】西南方之卦。【镇星入卦配坤，西南。】星宿从位降癸酉金。【二十八宿，八卦星</p><p>宿，降坤上六癸酉金。】分气候三十六。【起积为数三十六。】</p><p>阴中有阳，气积万象，故曰阴中阴。阴阳二气，天地相接，人事吉凶，见乎其象。六位适变，八卦分焉。【六位变动，八</p><p>卦显著。】阴虽虚纳，于阳位称实。【六五，六三之类也。】</p><p>升降反复，不能久处，千变万化，故称乎易。易者，变也。阴极则阳来，阴消则阳长，衰则退，盛则战。《易》云：“上</p><p>六，龙战于野，其血玄黄”。阳属。【乾配西北积阴之的地，阴盛故战，乾坤并处，天地之气杂，称玄黄也。】</p><p>阳来荡阴，坤内卦初六适变入阳，曰震。阴盛阳微，渐来之义，故称复。次降阳，入地雷复卦。</p>',12)])])}const m=e(i,[["render",r]]);export{h as __pageData,m as default};
